#include "icons_data.h"

const uint8_t *icon_get_rgba(int icon_id) {
    switch (icon_id) {
        case ICON_FOLDER:   return icon_folder_rgba;
        case ICON_TXT:      return icon_txt_rgba;
        case ICON_CODE:     return icon_code_rgba;
        case ICON_PROGRAM:  return icon_program_rgba;
        case ICON_TERMINAL: return icon_terminal_rgba;
        case ICON_SETTINGS: return icon_settings_rgba;
        case ICON_TRASH:    return icon_trash_rgba;
        case ICON_DISK:     return icon_disk_rgba;
        case ICON_NETWORK:  return icon_network_rgba;
        case ICON_LOCK:     return icon_lock_rgba;
        case ICON_MAIL:     return icon_mail_rgba;
        case ICON_COMPASS:  return icon_compass_rgba;
        case ICON_ANCHOR:   return icon_anchor_rgba;
        case ICON_PAINT: return icon_paint_rgba;
        case ICON_DESIGN: return icon_design_rgba;
        case ICON_LUA: return icon_lua_rgba;
        case ICON_IMAGE: return icon_image_rgba;
        case ICON_GAME: return icon_game_rgba;
        case ICON_MUSIC: return icon_music_rgba;
        case ICON_CLOCK: return icon_clock_rgba;
        case ICON_CALC: return icon_calc_rgba;
        case ICON_HELP: return icon_help_rgba;
        case ICON_INFO: return icon_info_rgba;
        case ICON_BOOK: return icon_book_rgba;
        case ICON_NAUTILUS: return icon_nautilus_rgba;
        default:            return 0;
    }
}

// Numero total de iconos del catalogo (0..N-1) -- lo usa el editor de
// escritorio para saber cuantos ofrecer al elegir.
uint32_t icon_catalog_count(void) { return 25; }
